// Manual Bearer check so the workflow imports without needing a credential.
// Replace REPLACE_WITH_XERO_N8N_SECRET with the same value you set as
// XERO_N8N_SECRET in the SPM prod .env.
const SECRET = 'REPLACE_WITH_XERO_N8N_SECRET';

const headers = $input.item.json.headers || {};
const auth = headers.authorization || headers.Authorization || '';

if (auth !== `Bearer ${SECRET}`) {
  throw new Error('Unauthorized: bad or missing Bearer token');
}

// Pass through the body so downstream nodes see it as $json.
return { json: $input.item.json.body || {} };

// ─── EDIT THESE FOUR, THEN NOTHING ELSE IN THIS WORKFLOW ──────────────
//
// ACCOUNT_CODE   Chart-of-accounts code the support revenue posts to.
//                Xero: Accounting → Chart of Accounts → the Code column.
// TAX_TYPE       Tax rate to apply. Xero: Accounting → Advanced → Tax Rates.
//                Common: 'NONE' (no tax), 'OUTPUT2' (UK 20%),
//                'ZERORATEDEUSERVICES' (EU B2B reverse charge).
// LINE_AMOUNTS   'Inclusive' if the Stripe amount already contains tax
//                (usually true), 'Exclusive' if tax should be added on top.
// ORG_NAME       Leave '' to use the first connected org. Set it only if the
//                credential is connected to more than one Xero org.
//
const ACCOUNT_CODE = '200';
const TAX_TYPE = 'NONE';
const LINE_AMOUNTS = 'Inclusive';
const ORG_NAME = '';
// ─────────────────────────────────────────────────────────────────────

const spm = $('Verify Bearer').first().json;

// /connections returns one row per connected org.
const connections = $input.all().map((i) => i.json);
const connection = ORG_NAME
  ? connections.find((c) => c.tenantName === ORG_NAME)
  : connections[0];

if (!connection || !connection.tenantId) {
  throw new Error(
    ORG_NAME
      ? `No connected Xero org named "${ORG_NAME}". Connected: ${connections.map((c) => c.tenantName).join(', ') || 'none'}`
      : 'No Xero org connected — reconnect the OAuth2 credential.',
  );
}

const hours = Number(spm.hours) || 0;
const amount = Number(spm.amountEur) || 0;
if (hours <= 0) throw new Error(`Bad hours in SPM payload: ${spm.hours}`);
if (amount <= 0) throw new Error(`Bad amountEur in SPM payload: ${spm.amountEur}`);

// SPM sends the gross total; Xero wants a unit price. Divide back out and
// keep 4dp so the line total reconstructs to the same figure Stripe charged.
const unitAmount = Number((amount / hours).toFixed(4));

// If SPM already knows the Xero ContactID, use it. Otherwise pass the name —
// Xero matches an existing contact by name, or auto-creates one.
const contact = spm.xeroContactId
  ? { ContactID: spm.xeroContactId }
  : {
      Name: spm.tenantName || `SPM tenant ${spm.tenantId}`,
      ...(spm.contactEmail ? { EmailAddress: spm.contactEmail } : {}),
    };

const today = new Date().toISOString().slice(0, 10);

const invoicePayload = {
  Invoices: [
    {
      Type: 'ACCREC',
      Contact: contact,
      Date: today,
      // Already paid via Stripe, so no credit terms — due same day.
      DueDate: today,
      Status: 'AUTHORISED',
      CurrencyCode: (spm.currency || 'EUR').toUpperCase(),
      // Stripe session id lands in Reference so accounting can tie the Xero
      // record back to the payment without leaving Xero.
      Reference: spm.stripeSessionId || '',
      LineAmountTypes: LINE_AMOUNTS,
      LineItems: [
        {
          Description: spm.description || `SPM: ${hours} support-hour credits`,
          Quantity: hours,
          UnitAmount: unitAmount,
          AccountCode: ACCOUNT_CODE,
          TaxType: TAX_TYPE,
        },
      ],
    },
  ],
};

return [
  {
    json: {
      xeroTenantId: connection.tenantId,
      xeroTenantName: connection.tenantName,
      stripeSessionId: spm.stripeSessionId ?? null,
      invoicePayload,
    },
  },
];
